import static org.assertj.core.api.Assertions.assertThat;
import static org.junit.jupiter.api.Assertions.assertAll;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.File;
import java.io.IOException;
import java.util.List;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;

import org.eclipse.rdf4j.common.transaction.IsolationLevels;
import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.sail.NotifyingSailConnection;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.eclipse.rdf4j.sail.lmdb.model.LmdbValue;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.Timeout;
import org.junit.jupiter.api.io.TempDir;

class LmdbPostReadyRetirementHorizonTest {
	@Test
	@Timeout(30)
	void delayedStartupRecoveryProtectsReadersAdmittedAfterItsHorizonWasCaptured(@TempDir File directory)
			throws Exception {
		CountDownLatch horizonCaptured = new CountDownLatch(1);
		CountDownLatch releaseRecovery = new CountDownLatch(1);
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc,ospc").setAsyncValueCleanup(false)
				.setDirectAdjacencyEnabled(false)
				.setValueOverlayEnabled(false);
		LmdbStore store = new LmdbStore(directory, config) {
			@Override
			LmdbSailStore createBackingStore(File root, StoreProperties properties, LmdbStoreConfig options,
					boolean sketches) throws IOException {
				return new LmdbSailStore(root, properties, options, sketches,
						(path, valueProperties, valueConfig) -> new ValueStore(path, valueProperties, valueConfig) {
							@Override
							void startIndexRebuildAfterStoreInitialization() {
								super.startIndexRebuildAfterStoreInitialization();
								// Install only on the real post-ready caller, not on foreground committers.
								LmdbStartupDiagnostics.OBSERVER.set(operation -> {
									if (operation == LmdbStartupDiagnostics.Operation.RETIREMENT_RECOVERY) {
										LmdbStartupDiagnostics.OBSERVER.remove();
										// The recovery method's horizon argument has already been evaluated.
										horizonCaptured.countDown();
										try {
											assertTrue(releaseRecovery.await(20, TimeUnit.SECONDS));
										} catch (InterruptedException failure) {
											Thread.currentThread().interrupt();
											throw new AssertionError(failure);
										}
									}
								});
							}
						}, TripleStore::new);
			}
		};
		try {
			store.init();
			assertTrue(horizonCaptured.await(10, TimeUnit.SECONDS));
			var vf = SimpleValueFactory.getInstance();
			IRI predicate = vf.createIRI("urn:horizon:p");
			IRI older = vf.createIRI("urn:horizon:v");
			IRI newer = vf.createIRI("urn:horizon:w");
			try (var writer = store.getConnection()) {
				writer.begin();
				writer.addStatement(older, predicate, vf.createLiteral("v-value"));
				writer.addStatement(newer, predicate, vf.createLiteral("w-value"));
				writer.addStatement(vf.createIRI("urn:horizon:keeper"), predicate, vf.createLiteral("keep"));
				writer.commit();
			}
			try (var readerA = store.getConnection()) {
				readerA.begin(IsolationLevels.SNAPSHOT);
				assertThat(objects(readerA, older, predicate)).containsExactly("v-value");
				remove(store, older, predicate);
				assertThat(objects(readerA, older, predicate)).containsExactly("v-value");
				readerA.commit();
			}
			try (var readerB = store.getConnection()) {
				readerB.begin(IsolationLevels.SNAPSHOT);
				assertThat(objects(readerB, newer, predicate)).containsExactly("w-value");
				remove(store, newer, predicate);
				ValueStore values = store.getBackingStore().valueStore();
				assertThat(values.getId(older)).isEqualTo(LmdbValue.UNKNOWN_ID);
				assertThat(values.getId(newer)).isNotEqualTo(LmdbValue.UNKNOWN_ID);
				releaseRecovery.countDown();
				LmdbTestUtil.awaitPostReadyInitialization(store, 10, TimeUnit.SECONDS);
				assertAll("startup recovery must respect the reader admitted after its stale horizon",
						() -> assertThat(values.getId(newer)).isNotEqualTo(LmdbValue.UNKNOWN_ID),
						() -> assertThat(objects(readerB, newer, predicate)).containsExactly("w-value"));
				readerB.commit();
			}
		} finally {
			releaseRecovery.countDown();
			store.shutDown();
		}
	}

	private static void remove(LmdbStore store, IRI subject, IRI predicate) {
		try (var writer = store.getConnection()) {
			writer.begin(IsolationLevels.NONE);
			writer.removeStatements(subject, predicate, null);
			writer.commit();
		}
	}

	private static List<String> objects(NotifyingSailConnection reader, IRI subject, IRI predicate) {
		try (var rows = reader.getStatements(subject, predicate, null, false)) {
			return rows.stream().map(statement -> statement.getObject().stringValue()).sorted().toList();
		}
	}
}
